if (isLoggedIn) {
    // lastKnownSession is only as fresh as its last write; re-prime under
    // the *current* token before reading it, or a login transition pairs
    // the new token with the previous account's recorded profile.
    try {
        userSessionRepository.primeSession()
    } catch (e: CancellationException) {
        throw e
    } catch (e: Exception) {
        Logger.w(e) { "Session re-prime failed; skipping warm-up" }
    }
}
_state.update {
    it.copy(
        isLoggedIn = isLoggedIn,
        signedInAvatarUrl = userSessionRepository.lastKnownSession
            ?.takeIf { session -> session.isLoggedIn }
            ?.profile
            ?.imageUrl,
    )
}

